CREATE TABLE schema_version (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE app_config_versions (version INTEGER PRIMARY KEY, config_hash TEXT NOT NULL, updated_at TEXT NOT NULL, changed_by TEXT NOT NULL);
CREATE TABLE assets (asset_id TEXT PRIMARY KEY, market TEXT NOT NULL, venue TEXT NOT NULL, symbol TEXT NOT NULL, type TEXT NOT NULL, currency TEXT NOT NULL, leveraged INTEGER NOT NULL, eligibility_status TEXT NOT NULL, trading_enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE allowlist (asset_id TEXT NOT NULL REFERENCES assets(asset_id), config_version INTEGER NOT NULL REFERENCES app_config_versions(version), enabled INTEGER NOT NULL, verified_at TEXT, PRIMARY KEY(asset_id, config_version));
CREATE TABLE account_snapshots (snapshot_id TEXT PRIMARY KEY, mode TEXT NOT NULL, as_of_utc TEXT NOT NULL, data_json TEXT NOT NULL, external_hash TEXT NOT NULL);
CREATE TABLE quotes (asset_id TEXT NOT NULL REFERENCES assets(asset_id), as_of_utc TEXT NOT NULL, source TEXT NOT NULL, bid TEXT, ask TEXT, last TEXT NOT NULL, delayed INTEGER NOT NULL, PRIMARY KEY(asset_id, as_of_utc, source));
CREATE TABLE evidence (evidence_id TEXT PRIMARY KEY, asset_ids_json TEXT NOT NULL, source_url TEXT NOT NULL, published_at TEXT NOT NULL, fetched_at TEXT NOT NULL, source_hash TEXT NOT NULL, publisher TEXT NOT NULL, text_excerpt TEXT NOT NULL);
CREATE TABLE theses (thesis_id TEXT NOT NULL, version INTEGER NOT NULL, asset_id TEXT NOT NULL REFERENCES assets(asset_id), status TEXT NOT NULL, premise TEXT NOT NULL, invalidation_json TEXT NOT NULL, evidence_ids_json TEXT NOT NULL, horizon_days INTEGER NOT NULL CHECK(horizon_days > 0), PRIMARY KEY(thesis_id, version));
CREATE TABLE agent_runs (run_id TEXT PRIMARY KEY, state_version INTEGER NOT NULL, mode TEXT NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, input_hash TEXT NOT NULL, result TEXT, failure_reason TEXT, started_utc TEXT NOT NULL, completed_utc TEXT);
CREATE TABLE decisions (decision_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES agent_runs(run_id), proposal_json TEXT NOT NULL, evidence_ids_json TEXT NOT NULL, state_version INTEGER NOT NULL, schema_valid INTEGER NOT NULL);
CREATE TABLE decision_validation_failures (decision_id TEXT PRIMARY KEY, failure_code TEXT NOT NULL, recorded_utc TEXT NOT NULL);
CREATE TABLE risk_checks (id TEXT PRIMARY KEY, decision_id TEXT NOT NULL REFERENCES decisions(decision_id), check_code TEXT NOT NULL, passed INTEGER NOT NULL, actual TEXT, limit_value TEXT, reason TEXT);
CREATE TABLE order_intents (intent_id TEXT PRIMARY KEY, decision_id TEXT NOT NULL REFERENCES decisions(decision_id), mode TEXT NOT NULL, asset_id TEXT NOT NULL REFERENCES assets(asset_id), side TEXT NOT NULL, qty TEXT NOT NULL, limit_price TEXT NOT NULL, ccy TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL);
CREATE TABLE order_events (event_id TEXT PRIMARY KEY, intent_id TEXT NOT NULL REFERENCES order_intents(intent_id), status TEXT NOT NULL, created_utc TEXT NOT NULL);
CREATE TRIGGER order_events_no_replace BEFORE INSERT ON order_events WHEN EXISTS (SELECT 1 FROM order_events WHERE event_id = NEW.event_id) BEGIN SELECT RAISE(ABORT, 'order events are append-only'); END;
CREATE TRIGGER order_events_no_update BEFORE UPDATE ON order_events BEGIN SELECT RAISE(ABORT, 'order events are append-only'); END;
CREATE TRIGGER order_events_no_delete BEFORE DELETE ON order_events BEGIN SELECT RAISE(ABORT, 'order events are append-only'); END;
CREATE TABLE broker_orders (local_order_id TEXT PRIMARY KEY, intent_id TEXT NOT NULL REFERENCES order_intents(intent_id), broker_order_id TEXT, mode TEXT NOT NULL, status TEXT NOT NULL, created_utc TEXT NOT NULL, updated_utc TEXT NOT NULL);
CREATE TABLE fills (broker_order_id TEXT NOT NULL, fill_id TEXT NOT NULL, qty TEXT NOT NULL, price TEXT NOT NULL, ccy TEXT NOT NULL, fee TEXT NOT NULL, tax TEXT NOT NULL, filled_at TEXT NOT NULL, PRIMARY KEY(broker_order_id, fill_id));
CREATE TABLE cashflows (cashflow_id TEXT PRIMARY KEY, type TEXT NOT NULL, amount TEXT NOT NULL, currency TEXT NOT NULL, timestamp TEXT NOT NULL, broker_ref TEXT);
CREATE TABLE model_usage (run_id TEXT NOT NULL REFERENCES agent_runs(run_id), provider TEXT NOT NULL, model TEXT NOT NULL, seq INTEGER NOT NULL, latency TEXT, input_tokens INTEGER, output_tokens INTEGER, call_count INTEGER, failure TEXT, estimated_cost TEXT, PRIMARY KEY(run_id, provider, model, seq));
CREATE TABLE evaluations (eval_id TEXT PRIMARY KEY, start TEXT NOT NULL, end TEXT NOT NULL, baseline TEXT NOT NULL, twr TEXT, mdd TEXT, cost TEXT, method_version TEXT NOT NULL);
CREATE TABLE runtime_locks (singleton INTEGER PRIMARY KEY CHECK(singleton = 1), acquired_at TEXT NOT NULL, pid INTEGER NOT NULL, heartbeat TEXT NOT NULL);
